
<style>
    :root {

        /* ========================================
       AI VOICE — COLOR SYSTEM
        ======================================== */

        /* ---------- Primary ---------- */
        --ai-orange: #EA5C28;
        --ai-orange-bright: #F4511E;
        --ai-orange-dark: #D94717;

        /* ---------- Secondary ---------- */
        --ai-red: #E3413E;
        --ai-pink: #E31D5B;
        --ai-pink-light: #EC4899;

        /* ---------- Gradients ---------- */
        --ai-gradient: linear-gradient(90deg,
                #F4511E 0%,
                #E3413E 50%,
                #E31D5B 100%);

        --ai-gradient-reverse: linear-gradient(90deg,
                #E31D5B 0%,
                #E3413E 50%,
                #F4511E 100%);

        --ai-gradient-soft: linear-gradient(135deg,
                rgba(244, 81, 30, 0.12),
                rgba(227, 29, 91, 0.12));


        /* ========================================
       DARK / AI SECTIONS
        ======================================== */

        --ai-dark: #120E20;
        --ai-dark-secondary: #171126;
        --ai-dark-purple: #251636;
        --ai-dark-card: #1F1A31;
        --ai-dark-card-hover: #2A2040;

        --ai-dark-border: rgba(255, 255, 255, 0.08);

        --ai-dark-text: #FFFFFF;
        --ai-dark-text-secondary: #E5E7EB;
        --ai-dark-text-muted: #A1A1AA;


        /* ========================================
       LIGHT SECTIONS
        ======================================== */

        --ai-white: #FFFFFF;
        --ai-bg: #FFFFFF;

        --ai-bg-warm: #FFF6EE;
        --ai-bg-soft: #FEF3F1;
        --ai-bg-orange: #FFF1E8;

        --ai-bg-pink: #FFF1F5;
        --ai-bg-purple: #F7F3FF;


        /* ========================================
       TEXT
        ======================================== */

        --ai-text: #111827;
        --ai-text-heading: #111827;
        --ai-text-body: #374151;
        --ai-text-muted: #6B7280;
        --ai-text-light: #9CA3AF;

        --ai-text-white: #FFFFFF;


        /* ========================================
       BORDERS
        ======================================== */

        --ai-border: #E5E7EB;
        --ai-border-light: #F3F4F6;
        --ai-border-orange: rgba(234, 92, 40, 0.25);
        --ai-border-pink: rgba(227, 29, 91, 0.20);


        /* ========================================
       CARDS
        ======================================== */

        --ai-card-bg: #FFFFFF;
        --ai-card-bg-soft: #FFF9F5;

        --ai-card-shadow:
            0 4px 20px rgba(17, 24, 39, 0.06);

        --ai-card-shadow-hover:
            0 12px 35px rgba(17, 24, 39, 0.10);


        /* ========================================
       STATUS / UI COLORS
        ======================================== */

        --ai-success: #22C55E;
        --ai-success-light: #DCFCE7;

        --ai-warning: #F59E0B;
        --ai-warning-light: #FEF3C7;

        --ai-info: #3B82F6;
        --ai-info-light: #DBEAFE;

        --ai-danger: #EF4444;
        --ai-danger-light: #FEE2E2;


        /* ========================================
       VOICE / WAVEFORM
        ======================================== */

        --ai-wave-primary: #F4511E;
        --ai-wave-secondary: #E31D5B;
        --ai-wave-light: rgba(244, 81, 30, 0.20);

        --ai-pulse: rgba(234, 92, 40, 0.25);


        /* ========================================
       BUTTONS
        ======================================== */

        --ai-btn-primary: #EA5C28;
        --ai-btn-primary-hover: #D94717;

        --ai-btn-gradient: linear-gradient(90deg,
                #F4511E,
                #E31D5B);

        --ai-btn-text: #FFFFFF;


        /* ========================================
       RADIUS
        ======================================== */

        --ai-radius-sm: 6px;
        --ai-radius-md: 10px;
        --ai-radius-lg: 14px;
        --ai-radius-xl: 20px;
        --ai-radius-full: 999px;


        /* ========================================
       SPACING
        ======================================== */

        --ai-section-padding: 100px;
        --ai-container-width: 1200px;


        /* ========================================
       TRANSITIONS
        ======================================== */

        --ai-transition-fast: 0.2s ease;
        --ai-transition: 0.3s ease;
        --ai-transition-slow: 0.5s ease;
    }


    /* ========================================
       AI TECH SECTION
    ======================================== */

    .ai-tech {
        position: relative;
        background: radial-gradient(circle at 15% 10%, rgba(244, 81, 30, 0.35), transparent 45%),
                    radial-gradient(circle at 85% 0%, rgba(227, 29, 91, 0.30), transparent 45%),
                    radial-gradient(circle at 50% 100%, rgba(124, 58, 237, 0.20), transparent 50%),
                    var(--ai-dark);
        padding: var(--ai-section-padding) 0;
        overflow: hidden;
    }

    .ai-tech_content {
        position: relative;
        z-index: 1;
        max-width: var(--ai-container-width);
        margin: 0 auto;
        padding: 0 40px;
    }

    /* ---------- Heading block ---------- */

    .ai-tech_content--heading {
        text-align: center;
        max-width: 720px;
        margin: 0 auto 60px;
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .ai-tech_content--eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        background: rgba(255, 255, 255, 0.06);
        border: 1px solid var(--ai-dark-border);
        color: var(--ai-dark-text-secondary);
        font-size: 13px;
        font-weight: 600;
        letter-spacing: 0.2px;
        padding: 7px 16px 7px 12px;
        border-radius: var(--ai-radius-full);
        margin-bottom: 22px;
    }

    .ai-tech_content--eyebrow span svg {
        width: 15px;
        height: 15px;
        display: block;
    }

    .ai-tech_content--eyebrow span svg path,
    .ai-tech_content--eyebrow span svg .st0 {
        fill: var(--ai-orange-bright);
    }

    .ai-tech_content--heading h1,
    h1.ai-tech_content--heading {
        font-size: 44px;
        line-height: 1.15;
        font-weight: 800;
        letter-spacing: -1px;
        color: var(--ai-dark-text);
        margin-bottom: 18px;
    }

    .ai-tech_content--para {
        font-size: 17px;
        line-height: 1.65;
        color: var(--ai-dark-text-muted);
        margin-bottom: 26px;
    }

    .ai-tech_content--badge {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        background: rgba(255, 255, 255, 0.05);
        border: 1px solid var(--ai-dark-border);
        border-radius: var(--ai-radius-full);
        padding: 10px 20px;
        backdrop-filter: blur(6px);
    }

    .ai-tech_content--badge span {
        width: 24px;
        height: 24px;
        border-radius: 50%;
        background: var(--ai-gradient);
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }

    .ai-tech_content--badge span svg {
        width: 12px;
        height: 12px;
    }

    .ai-tech_content--badge span svg path {
        fill: var(--ai-white);
    }

    .ai-tech_content--badge p {
        font-size: 13px;
        color: var(--ai-dark-text-secondary);
    }

    .ai-tech_content--badge p span {
        all: unset;
        font-weight: 700;
        color: var(--ai-dark-text);
    }

    /* ---------- Cards grid ---------- */

    .ai-tech_content--card-container {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 24px;
    }

    .ai-tech_content--card {
        position: relative;
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        padding: 28px 24px;
        border-radius: var(--ai-radius-xl);
        background: rgba(255, 255, 255, 0.06);
        border: 1px solid rgba(255, 255, 255, 0.12);
        backdrop-filter: blur(16px);
        -webkit-backdrop-filter: blur(16px);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
        overflow: hidden;
        transition: var(--ai-transition);
    }

    .ai-tech_content--card::before {
        content: "";
        position: absolute;
        inset: 0;
        background: linear-gradient(160deg, rgba(255, 255, 255, 0.10), rgba(255, 255, 255, 0) 45%);
        pointer-events: none;
    }

    .ai-tech_content--card:hover {
        background: rgba(255, 255, 255, 0.10);
        border-color: rgba(255, 255, 255, 0.22);
        transform: translateY(-4px);
        box-shadow: 0 16px 40px rgba(0, 0, 0, 0.35);
    }

    .ai-tech_content--card .icon {
        width: 48px;
        height: 48px;
        border-radius: var(--ai-radius-md);
        background: var(--ai-gradient);
        display: flex;
        align-items: center;
        justify-content: center;
        margin-bottom: auto;
        flex-shrink: 0;
    }

    .ai-tech_content--card .icon svg {
        width: 22px;
        height: 22px;
    }

    .ai-tech_content--card .icon svg path {
        fill: var(--ai-white);
    }

    .ai-tech_content--card .card-brow {
        font-size: 12px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.6px;
        color: var(--ai-pink-light);
        margin-top: 22px;
        margin-bottom: 10px;
    }

    .ai-tech_content--card .card-heading {
        font-size: 19px;
        font-weight: 700;
        line-height: 1.3;
        color: var(--ai-dark-text);
        margin-bottom: 12px;
    }

    .ai-tech_content--card .card-para {
        font-size: 14px;
        line-height: 1.6;
        color: var(--ai-dark-text-muted);
    }

    /* ---------- Responsive ---------- */

    @media (max-width: 980px) {
        .ai-tech_content--card-container {
            grid-template-columns: repeat(2, 1fr);
        }
    }

    @media (max-width: 640px) {
        .ai-tech_content--card-container {
            grid-template-columns: 1fr;
        }

        .ai-tech_content--card {
            aspect-ratio: auto;
        }

        h1.ai-tech_content--heading {
            font-size: 32px;
        }
    }
</style>


